import './host'

import { MembershipService } from '@graft/nuget-gc.webportals.memberships'

import { getSessionToken } from '@common/helpers'
import { isVisionLocal } from '@common/utils/isVisionLocal'
import { readGraftObject } from '@common/utils/readGraftObject'

import type { InvitationOperationResult } from '@modules/invitation/invitation.interface'
import { mapGraftInvitationOperationResult } from '@modules/invitation/mappers/mapGraftInvitationOperationResult'
import { hasInvitationLinkParams } from '@modules/invitation/utils/hasInvitationLinkParams'

import type { Invitation } from './memberships.type'
import { isMembershipsServiceConfigured } from './memberships.utils'

const emptyInvitationOperationResult = (): InvitationOperationResult => ({
  succeeded: false,
  outcome: '',
  message: '',
  invitationId: '',
  operationId: '',
})

export async function getInvitations(): Promise<Invitation[]> {
  try {
    if (isVisionLocal() || !isMembershipsServiceConfigured()) {
      return []
    }

    const token = await getSessionToken()
    const invitations = await MembershipService.getInvitations(token)

    if (!invitations?.length) {
      return []
    }

    return Promise.all(invitations.map((invitation) => readGraftObject<Invitation>(invitation)))
  } catch (error) {
    console.error('Failed to get invitations:', error)
    return []
  }
}

export async function acceptInvitation(
  invitationId: string,
  expiresAtUnix?: string,
  signature?: string
): Promise<InvitationOperationResult> {
  if (isVisionLocal() || !isMembershipsServiceConfigured()) {
    return emptyInvitationOperationResult()
  }

  try {
    const token = await getSessionToken()
    const raw = hasInvitationLinkParams(expiresAtUnix, signature)
      ? await MembershipService.acceptInvitationFromLink(token, invitationId, expiresAtUnix ?? '', signature ?? '')
      : await MembershipService.acceptInvitation(token, invitationId)

    return mapGraftInvitationOperationResult(raw)
  } catch (error) {
    console.error('Failed to accept invitation:', error)
    throw error
  }
}

