async function assertMembershipSuccess(success: boolean, errorMessage: string): Promise<void> {
  if (!success) {
    throw new Error(errorMessage)
  }
}

export async function deleteWorkspaceMembership(workspaceId: string, deletedUserId: string): Promise<void> {
  if (isVisionLocal() || !isMembershipsServiceConfigured()) {
    return
  }

  try {
    const token = await getSessionToken()
    await assertMembershipSuccess(
      await MembershipService.deleteWorkspaceMembership(token, workspaceId, deletedUserId),
      'Failed to remove workspace member'
    )
  } catch (error) {
    console.error('Failed to remove workspace member:', error)
    throw error
  }
}

