import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";
import { Invitation } from "./Invitation.js";
import { InvitationOperationResult } from "./InvitationOperationResult.js";

export class MembershipService {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.Memberships.Facade.MembershipService",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} deletedUserId
   * @returns {Promise<boolean>}
   */
  static async deleteProjectMembership(token, projectId, deletedUserId) {
    try {
      const returnObjectIC = await MembershipService.type
        .invokeStaticMethod(
          "DeleteProjectMembership",
          token,
          projectId,
          deletedUserId,
        )
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} workspaceId
   * @param {string} deletedUserId
   * @returns {Promise<boolean>}
   */
  static async deleteWorkspaceMembership(token, workspaceId, deletedUserId) {
    try {
      const returnObjectIC = await MembershipService.type
        .invokeStaticMethod(
          "DeleteWorkspaceMembership",
          token,
          workspaceId,
          deletedUserId,
        )
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} membershipLevel
   * @param {string} email
   * @param {string} region
   * @returns {Promise<InvitationOperationResult>}
   */
  static async inviteProjectMember(
    token,
    projectId,
    membershipLevel,
    email,
    region,
  ) {
    try {
      const returnObjectIC = await MembershipService.type
        .invokeStaticMethod(
          "InviteProjectMember",
          token,
          projectId,
          membershipLevel,
          email,
          region,
        )
        .execute();

      await GraftUtils.RegisterType(
        InvitationOperationResult,
        returnObjectIC,
        false,
      );
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} workspaceId
   * @param {string} membershipLevel
   * @param {string} email
   * @param {string} region
   * @returns {Promise<InvitationOperationResult>}
   */
  static async inviteWorkspaceMember(
    token,
    workspaceId,
    membershipLevel,
    email,
    region,
  ) {
    try {
      const returnObjectIC = await MembershipService.type
        .invokeStaticMethod(
          "InviteWorkspaceMember",
          token,
          workspaceId,
          membershipLevel,
          email,
          region,
        )
        .execute();

      await GraftUtils.RegisterType(
        InvitationOperationResult,
        returnObjectIC,
        false,
      );
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} invitationId
   * @param {string} expiresAtUnix
   * @param {string} signature
   * @returns {Promise<InvitationOperationResult>}
   */
  static async acceptInvitationFromLink(
    token,
    invitationId,
    expiresAtUnix,
    signature,
  ) {
    try {
      const returnObjectIC = await MembershipService.type
        .invokeStaticMethod(
          "AcceptInvitationFromLink",
          token,
          invitationId,
          expiresAtUnix,
          signature,
        )
        .execute();

      await GraftUtils.RegisterType(
        InvitationOperationResult,
        returnObjectIC,
        false,
      );
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} invitationId
   * @returns {Promise<InvitationOperationResult>}
   */
  static async acceptInvitation(token, invitationId) {
    try {
      const returnObjectIC = await MembershipService.type
        .invokeStaticMethod("AcceptInvitation", token, invitationId)
        .execute();

      await GraftUtils.RegisterType(
        InvitationOperationResult,
        returnObjectIC,
        false,
      );
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} invitationId
   * @returns {Promise<InvitationOperationResult>}
   */
  static async cancelInvitation(token, invitationId) {
    try {
      const returnObjectIC = await MembershipService.type
        .invokeStaticMethod("CancelInvitation", token, invitationId)
        .execute();

      await GraftUtils.RegisterType(
        InvitationOperationResult,
        returnObjectIC,
        false,
      );
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} invitationId
   * @returns {Promise<InvitationOperationResult>}
   */
  static async declineInvitation(token, invitationId) {
    try {
      const returnObjectIC = await MembershipService.type
        .invokeStaticMethod("DeclineInvitation", token, invitationId)
        .execute();

      await GraftUtils.RegisterType(
        InvitationOperationResult,
        returnObjectIC,
        false,
      );
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @returns {Promise<Invitation[]>}
   */
  static async getInvitations(token) {
    try {
      const returnObjectIC = await MembershipService.type
        .invokeStaticMethod("GetInvitations", token)
        .execute();

      await GraftUtils.RegisterType(Invitation, returnObjectIC, true);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @returns {Promise<boolean>}
   */
  static async isHealthy() {
    try {
      const returnObjectIC = await MembershipService.type
        .invokeStaticMethod("IsHealthy")
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }
}
